# extracao.tf — a infraestrutura do corte: banco proprio, fila, e os dois papeis

# ── O banco do servico extraido. Nao e o mesmo RDS do monolito. ───────────────
resource "aws_db_instance" "notificacoes" {
  identifier     = "${var.projeto}-notificacoes"
  engine         = "postgres"
  engine_version = "16"
  instance_class = "db.t4g.micro" # volume baixo: so o log de envio, sem pedido nem catalogo

  db_name  = "notificacoes"
  username = "app"
  manage_master_user_password = true # segredo gerenciado pelo Secrets Manager, nunca em variavel

  allocated_storage = 20
  db_subnet_group_name   = aws_db_subnet_group.privada.name
  vpc_security_group_ids = [aws_security_group.rds_notificacoes.id]

  # Um ALTER TABLE aqui nao trava NENHUMA tabela do monolito: e um banco fisicamente
  # separado. E o ponto central do padrao "database per service".
  skip_final_snapshot = false
  final_snapshot_identifier = "${var.projeto}-notificacoes-final"
}

# O security group do RDS aceita conexao SO da task de notificacoes — nunca
# 0.0.0.0/0, e nunca a task do monolito, que nao tem nada para ler ali.
resource "aws_security_group_rule" "rds_notificacoes_entrada" {
  type                     = "ingress"
  from_port                = 5432
  to_port                  = 5432
  protocol                 = "tcp"
  security_group_id        = aws_security_group.rds_notificacoes.id
  source_security_group_id = aws_security_group.task_notificacoes.id
}

# ── A fila entre os dois servicos, com DLQ dedicada. ───────────────────────────
resource "aws_sqs_queue" "pedido_criado_dlq" {
  name                      = "${var.projeto}-pedido-criado-dlq"
  message_retention_seconds = 1209600 # 14 dias — o teto do SQS; da tempo de investigar sem perder a mensagem
}

resource "aws_sqs_queue" "pedido_criado" {
  name = "${var.projeto}-pedido-criado"

  # Nao alteramos o padrao de 30s de visibility timeout aqui de proposito: o
  # consumidor processa em centenas de ms, entao o padrao ja sobra. So vale
  # revisar se o processamento (envio via SES) ficar lento o suficiente para a
  # mensagem voltar a ficar visivel ANTES de terminar — meça no seu ambiente.
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.pedido_criado_dlq.arn
    maxReceiveCount      = 5 # cinco tentativas: falha transitoria se recupera antes disso
  })
}

# Quem pode escrever na fila e o SEGREDO de nao virar chamada sincrona: e o
# outbox worker do monolito, e mais ninguem.
resource "aws_sqs_queue_policy" "somente_outbox_publica" {
  queue_url = aws_sqs_queue.pedido_criado.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { AWS = aws_iam_role.task_monolito.arn }
      Action    = "sqs:SendMessage"
      Resource  = aws_sqs_queue.pedido_criado.arn
    }]
  })
}

# ── Papel de tarefa do MONOLITO: so pode ENVIAR para a fila, nada alem disso. ──
data "aws_iam_policy_document" "monolito_publica_evento" {
  statement {
    effect    = "Allow"
    actions   = ["sqs:SendMessage"]
    resources = [aws_sqs_queue.pedido_criado.arn] # restrito a UMA fila; sem "*"
  }
}

# ── Papel de tarefa do servico de NOTIFICACOES: consome a fila e envia e-mail. ─
data "aws_iam_policy_document" "notificacoes_consome_e_envia" {
  statement {
    effect  = "Allow"
    actions = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes"]
    resources = [aws_sqs_queue.pedido_criado.arn] # restrito a mesma fila; sem "*"
  }
  statement {
    effect  = "Allow"
    actions = ["ses:SendEmail", "ses:SendRawEmail"]
    # Restrito a IDENTIDADE verificada, nao a conta inteira: o servico so pode
    # enviar EM NOME do dominio da Cadencia, nunca se passar por outro remetente.
    resources = [aws_ses_domain_identity.cadencia.arn]
  }
}

resource "aws_ecs_service" "notificacoes" {
  name            = "${var.projeto}-notificacoes"
  cluster         = aws_ecs_cluster.principal.id
  task_definition = aws_ecs_task_definition.notificacoes.arn
  desired_count   = 2
  launch_type     = "FARGATE"

  # Reusa o mesmo par mínimo/máximo do L03 — o rollout sem janela nao e
  # exclusivo do monolito; e propriedade de QUALQUER servico ECS bem configurado.
  deployment_minimum_healthy_percent = 100
  deployment_maximum_percent         = 200
  deployment_circuit_breaker { enable = true, rollback = true }

  network_configuration {
    subnets          = aws_subnet.privada[*].id
    security_groups  = [aws_security_group.task_notificacoes.id]
    assign_public_ip = false
  }
  # Sem load_balancer: este servico nao tem rota publica, so consome fila.
}

output "fila_pedido_criado" {
  value       = aws_sqs_queue.pedido_criado.url
  description = "URL da fila; o monolito publica aqui depois do commit"
}

// OutboxMessage.cs — a linha que garante que publicar nao e um passo separado do commit

public class OutboxMessage
{
    public Guid Id { get; set; }
    public string TipoEvento { get; set; } = "PedidoCriado";
    public string PayloadJson { get; set; } = default!;
    public DateTimeOffset CriadoEm { get; set; }
    public DateTimeOffset? PublicadoEm { get; set; } // null = ainda nao publicado
}

// PedidoService.cs — o ponto em que a garantia nasce
public async Task<Pedido> CriarPedidoAsync(NovoPedidoDto dto, AppDb db)
{
    // A verificacao de estoque e o decremento acontecem AQUI, na mesma
    // transacao do pedido — e e por isso que estoque NAO foi extraido.
    var produto = await db.Produtos.FindAsync(dto.ProdutoId)
        ?? throw new ProdutoNaoEncontradoException(dto.ProdutoId);
    if (produto.QuantidadeDisponivel < dto.Quantidade)
        throw new EstoqueInsuficienteException(dto.ProdutoId);
    produto.QuantidadeDisponivel -= dto.Quantidade;

    var pedido = new Pedido
    {
        Id = Guid.NewGuid(),
        ProdutoId = produto.Id,
        // Preco e nome SNAPSHOTADOS para dentro do pedido — e o que torna
        // Catalogo um candidato valido a extrair depois, sem quebrar pedido antigo.
        PrecoNoMomento = produto.Preco,
        NomeProdutoNoMomento = produto.Nome,
        Quantidade = dto.Quantidade,
        CriadoEm = DateTimeOffset.UtcNow,
    };
    db.Pedidos.Add(pedido);

    // A linha de outbox entra no MESMO SaveChanges do pedido. Ou as duas
    // sao commitadas juntas, ou nenhuma e — isto e o que fecha o dual-write
    // problem: nunca existe um pedido salvo sem a intencao de publicar salva.
    db.OutboxMessages.Add(new OutboxMessage
    {
        Id = Guid.NewGuid(),
        TipoEvento = "PedidoCriado",
        PayloadJson = JsonSerializer.Serialize(new PedidoCriadoEvento(
            pedido.Id, pedido.ProdutoId, pedido.NomeProdutoNoMomento, pedido.CriadoEm)),
        CriadoEm = DateTimeOffset.UtcNow,
    });

    await db.SaveChangesAsync(); // UM commit; pedido e outbox nascem juntos ou nao nascem
    return pedido;
}

// OutboxPublisherWorker.cs — o unico lugar que fala com a fila do lado do monolito

public class OutboxPublisherWorker(
    IServiceScopeFactory scopeFactory, IAmazonSQS sqs, IConfiguration config,
    ILogger<OutboxPublisherWorker> log) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        var filaUrl = config["Filas:PedidoCriado"]!;

        while (!ct.IsCancellationRequested)
        {
            using var escopo = scopeFactory.CreateScope();
            var db = escopo.ServiceProvider.GetRequiredService<AppDb>();

            // So le o que ainda nao foi publicado. A leitura NAO precisa de
            // lock especial: se dois workers rodassem em paralelo (nao roda,
            // desired_count controla isto por task), publicar duas vezes seria
            // absorvido pela idempotencia do CONSUMIDOR, nao daqui.
            var pendentes = await db.OutboxMessages
                .Where(m => m.PublicadoEm == null)
                .OrderBy(m => m.CriadoEm)
                .Take(50)
                .ToListAsync(ct);

            foreach (var msg in pendentes)
            {
                try
                {
                    await sqs.SendMessageAsync(new SendMessageRequest
                    {
                        QueueUrl = filaUrl,
                        MessageBody = msg.PayloadJson,
                        MessageAttributes = new()
                        {
                            ["TipoEvento"] = new MessageAttributeValue
                            { DataType = "String", StringValue = msg.TipoEvento },
                        },
                    }, ct);

                    msg.PublicadoEm = DateTimeOffset.UtcNow;
                }
                catch (Exception ex)
                {
                    // Nao marca como publicado. Fica pendente e tenta de novo
                    // no proximo ciclo — e a fila fora do ar NAO perde o pedido.
                    log.LogWarning(ex, "falha ao publicar outbox {Id}; tenta de novo no proximo ciclo", msg.Id);
                }
            }
            await db.SaveChangesAsync(ct);

            // O intervalo domina o atraso percebido na confirmacao — ver a
            // formula na secao de arquitetura de producao.
            await Task.Delay(TimeSpan.FromSeconds(2), ct);
        }
    }
}

// NotificacaoConsumerWorker.cs — o lado que le a fila e decide se envia

public class NotificacaoConsumerWorker(
    IAmazonSQS sqs, IAmazonSimpleEmailService ses, IServiceScopeFactory scopeFactory,
    IConfiguration config, ILogger<NotificacaoConsumerWorker> log) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        var filaUrl = config["Filas:PedidoCriado"]!;

        while (!ct.IsCancellationRequested)
        {
            var resposta = await sqs.ReceiveMessageAsync(new ReceiveMessageRequest
            {
                QueueUrl = filaUrl,
                MaxNumberOfMessages = 10,
                WaitTimeSeconds = 20, // long polling: evita custo e latencia de sondar vazio
            }, ct);

            foreach (var msg in resposta.Messages)
            {
                var evento = JsonSerializer.Deserialize<PedidoCriadoEvento>(msg.Body)!;
                using var escopo = scopeFactory.CreateScope();
                var db = escopo.ServiceProvider.GetRequiredService<NotificacaoDb>();

                // A CHECAGEM QUE IMPORTA. SQS padrao entrega PELO MENOS uma vez,
                // entao esta mensagem pode ser a segunda entrega da mesma
                // notificacao. E a linha abaixo, nao a fila, que impede o
                // segundo e-mail.
                var jaEnviado = await db.EnviosLog
                    .AnyAsync(e => e.PedidoId == evento.PedidoId, ct);

                if (!jaEnviado)
                {
                    await ses.SendEmailAsync(MontarEmailConfirmacao(evento), ct);
                    db.EnviosLog.Add(new EnvioLog
                    {
                        PedidoId = evento.PedidoId,
                        EnviadoEm = DateTimeOffset.UtcNow,
                    });
                    await db.SaveChangesAsync(ct);
                }
                else
                {
                    log.LogInformation("pedido {Id} ja tinha e-mail enviado; mensagem reentregue, ignorada",
                        evento.PedidoId);
                }

                // So apaga DEPOIS do envio (ou da checagem) ter sucesso. Se o
                // processo cair entre enviar e apagar, a reentrega vai bater
                // no log e nao reenviar — a mesma checagem cobre os dois casos.
                await sqs.DeleteMessageAsync(filaUrl, msg.ReceiptHandle, ct);
            }
        }
    }
}
